-- State transitions declared for MFADevice (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.mfa_devices_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: mfa_devices.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS mfa_devices_status_transition_check ON sapiens.mfa_devices;
CREATE TRIGGER mfa_devices_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.mfa_devices
    FOR EACH ROW EXECUTE FUNCTION sapiens.mfa_devices_status_transition_check();
